// vnToken is one design token. Dark is empty for tokens that do not change
// with the theme; they are declared once, in the light block. File names the
// one stylesheet that owns the token: ui-tokens.css (hand-written) or
// ui-accents.css (generated by scripts/build-accents.cjs).
type vnToken struct{ Group, Name, Light, Dark, File string }

const (
	tokensCSS  = "ui-tokens.css"
	accentsCSS = "ui-accents.css"
)

func staticTokens(group string, rows ...[3]string) []vnToken {
	out := make([]vnToken, 0, len(rows))
	for _, r := range rows {
		out = append(out, vnToken{group, r[0], r[1], r[2], tokensCSS})
	}
	return out
}

func lookTokens(group string, rows ...[3]string) []vnToken {
	out := staticTokens(group, rows...)
	for i := range out {
		out[i].File = accentsCSS
	}
	return out
}

func joinTokens(groups ...[]vnToken) []vnToken {
	var out []vnToken
	for _, g := range groups {
		out = append(out, g...)
	}
	return out
}

