// vnBlock returns the declarations of the rule whose selector starts at the
// last occurrence of header (the vNext blocks follow the legacy --gyst ones).
func vnBlock(t *testing.T, css, header string) map[string]string {
	t.Helper()
	i := strings.LastIndex(css, header)
	if i < 0 {
		t.Fatalf("token block %q missing", header)
	}
	body := css[i+len(header):]
	body = body[:strings.Index(body, "}")]
	body = regexp.MustCompile(`(?s)/\*.*?\*/`).ReplaceAllString(body, "")
	out := map[string]string{}
	for _, decl := range strings.Split(body, ";") {
		name, value, ok := strings.Cut(decl, ":")
		if name = strings.TrimSpace(name); ok && strings.HasPrefix(name, "--") {
			out[name] = strings.Join(strings.Fields(value), " ")
		}
	}
	return out
}

// cssRule is one style rule. Media is the enclosing at-rule's prelude, or "".
type cssRule struct {
	Media, Selector string
	Names           []string
	Decls           map[string]string
}

// has reports whether the rule's selector list contains sel exactly.
func (r cssRule) has(sel string) bool {
	for _, s := range strings.Split(r.Selector, ",") {
		if strings.TrimSpace(s) == sel {
			return true
		}
	}
	return false
}

var cssComment = regexp.MustCompile(`(?s)/\*.*?\*/`)

// parseCSS returns the style rules of a stylesheet in source order, one level
// of at-rule nesting deep, which is all these files use. Whitespace inside
// selectors and values is collapsed.
func parseCSS(css string) []cssRule {
	css = cssComment.ReplaceAllString(css, "")
	norm := func(s string) string { return strings.Join(strings.Fields(s), " ") }
	var rules []cssRule
	var walk func(body, media string)
	walk = func(body, media string) {
		for {
			open := strings.Index(body, "{")
			if open < 0 {
				return
			}
			prelude := norm(body[:open])
			depth, end := 1, open+1
			for ; end < len(body) && depth > 0; end++ {
				switch body[end] {
				case '{':
					depth++
				case '}':
					depth--
				}
			}
			inner := body[open+1 : end-1]
			body = body[end:]
			if strings.HasPrefix(prelude, "@media") || strings.HasPrefix(prelude, "@supports") {
				walk(inner, prelude)
				continue
			}
			r := cssRule{Media: media, Selector: prelude, Decls: map[string]string{}}
			for _, decl := range strings.Split(inner, ";") {
				name, value, ok := strings.Cut(decl, ":")
				if name = strings.TrimSpace(name); ok && name != "" {
					r.Names = append(r.Names, name)
					r.Decls[name] = norm(value)
				}
			}
			rules = append(rules, r)
		}
	}
	walk(css, "")
	return rules
}

func readStatic(t *testing.T, rel string) string {
	t.Helper()
	b, err := os.ReadFile("../../web/static/" + rel)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// The three theme blocks every token file uses.
const (
	selLight      = `:root, [data-gyst-theme="light"]`
	selSystemDark = `:root:not([data-gyst-theme="light"])`
	selDark       = `[data-gyst-theme="dark"]`
)

// themeBlocks returns the light, system-dark and explicit-dark rules of a
// token file. Each must exist exactly once.
func themeBlocks(t *testing.T, file string) (light, system, dark cssRule) {
	t.Helper()
	find := func(sel string, inMedia bool) cssRule {
		var found []cssRule
		for _, r := range parseCSS(readStatic(t, "css/"+file)) {
			// The token block is the one that declares --vn- names. The same selector also carries
			// the dark --gyst-border compatibility value (GYST-168), which is not a token.
			if r.Selector == sel && (r.Media != "") == inMedia && len(r.Names) > 0 && strings.HasPrefix(r.Names[0], "--vn-") {
				found = append(found, r)
			}
		}
		if len(found) != 1 {
			t.Fatalf("%s: %d rules for %q, want 1", file, len(found), sel)
		}
		return found[0]
	}
	system = find(selSystemDark, true)
	if system.Media != "@media (prefers-color-scheme: dark)" {
		t.Fatalf("%s: system dark block is inside %q", file, system.Media)
	}
	return find(selLight, false), system, find(selDark, false)
}

func TestVNextTokensDefinedLightAndDark(t *testing.T) {
	for _, file := range []string{tokensCSS, accentsCSS} {
		light, system, explicit := themeBlocks(t, file)
		for _, tok := range vnTokens {
			if tok.File != file {
				continue
			}
			if got := light.Decls[tok.Name]; got != tok.Light {
				t.Errorf("%s light %s = %q, want %q", file, tok.Name, got, tok.Light)
			}
			for mode, block := range map[string]cssRule{"system dark": system, "explicit dark": explicit} {
				got, ok := block.Decls[tok.Name]
				if tok.Dark == "" && ok {
					t.Errorf("%s %s: theme-independent %s must not be redeclared", file, mode, tok.Name)
				}
				if tok.Dark != "" && got != tok.Dark {
					t.Errorf("%s %s %s = %q, want %q", file, mode, tok.Name, got, tok.Dark)
				}
			}
		}
		// The system-dark and explicit-dark blocks must be the same set, or the
		// OS setting and the toggle would disagree.
		if len(system.Decls) != len(explicit.Decls) {
			t.Errorf("%s: system dark (%d) and explicit dark (%d) blocks differ", file, len(system.Decls), len(explicit.Decls))
		}
		for name, v := range explicit.Decls {
			if system.Decls[name] != v {
				t.Errorf("%s: %s is %q under the toggle and %q under the OS setting", file, name, v, system.Decls[name])
			}
		}
		for _, block := range []cssRule{light, system, explicit} {
			for name := range block.Decls {
				if !strings.HasPrefix(name, "--vn-") {
					t.Errorf("%s: theme block declares non-namespaced %s", file, name)
				}
			}
		}
		// A token whose value refers to another token is resolved where it is
		// declared, so it must be repeated in the dark blocks or a nested
		// theme scope would keep the outer theme's value (GYST-168).
		if file == tokensCSS {
			themed := map[string]bool{}
			for name := range explicit.Decls {
				themed[name] = true
			}
			for name := range parseAccentNames(t) {
				themed[name] = true
			}
			for name, v := range light.Decls {
				for _, ref := range regexp.MustCompile(`var\((--vn-[a-z0-9-]+)\)`).FindAllStringSubmatch(v, -1) {
					if themed[ref[1]] && explicit.Decls[name] == "" {
						t.Errorf("%s refers to the theme-dependent %s but is not repeated in the dark blocks", name, ref[1])
					}
				}
			}
		}
	}
	if regexp.MustCompile(`[^-]color-scheme\s*:`).MatchString(readStatic(t, "css/"+tokensCSS) + readStatic(t, "css/"+accentsCSS)) {
		t.Error("the token files must not set color-scheme (it restyles native controls on existing screens)")
	}
}

func parseAccentNames(t *testing.T) map[string]bool {
	t.Helper()
	names := map[string]bool{}
	for _, r := range parseCSS(readStatic(t, "css/"+accentsCSS)) {
		for _, n := range r.Names {
			names[n] = true
		}
	}
	return names
}

// One owner per token (GYST-168): a name declared in both files would make the
// result depend on link order, and the generator could no longer be trusted
// as the source of the Look and accent colours.
func TestEveryTokenHasOneOwner(t *testing.T) {
	accents := parseAccentNames(t)
	for _, r := range parseCSS(readStatic(t, "css/"+tokensCSS)) {
		for _, n := range r.Names {
			if accents[n] {
				t.Errorf("%s is declared in both ui-tokens.css (%s) and ui-accents.css", n, r.Selector)
			}
		}
	}
}

// 13B DD-6 (the rule 13A DD-4 kept): the accent never means good, warning or
// bad. No ok, warn or crit token may refer to an accent, section or project
// token. GYST-168 E4 holds info to literals as well until 13B O-12 is answered,
// because Iris would draw Working and Attention in violet.
func TestStateTokensNeverUseTheAccent(t *testing.T) {
	for _, file := range []string{tokensCSS, accentsCSS} {
		for _, r := range parseCSS(readStatic(t, "css/"+file)) {
			for name, v := range r.Decls {
				for _, state := range []string{"--vn-ok", "--vn-warn", "--vn-crit", "--vn-info"} {
					if name != state && !strings.HasPrefix(name, state+"-") {
						continue
					}
					if strings.Contains(v, "var(") {
						t.Errorf("%s: state token %s is %q; it must be a literal, not another token", file, name, v)
					}
				}
			}
		}
	}
}

type vnSwatch struct {
	Name, Light, Dark, Kind string
	Var                     template.CSS
}

type vnSwatchGroup struct {
	Label, Word string
	Tokens      []vnSwatch
	// StateStyle follows 11 §I: ok is quiet (--ink-2 text and a green dot),
	// info and idle use their text colour, only warn and crit are tinted chips.
	StateStyle template.CSS
}

type vnGallery struct {
	Themes                 []string
	Colors, States, Scales []vnSwatchGroup
}

// One word per state family from 11 §I; state is never shown by colour alone.
var vnStateStyles = map[string]template.CSS{
	"ok":   "color:var(--vn-ink-2)",
	"info": "color:var(--vn-info-text)",
	"warn": "color:var(--vn-warn-text);background:var(--vn-warn-soft)",
	"crit": "color:var(--vn-crit-text);background:var(--vn-crit-soft)",
	"idle": "color:var(--vn-idle-text)",
}

var vnStateWords = map[string]string{"ok": "Healthy", "info": "Working", "warn": "Stale", "crit": "Failed", "idle": "Paused"}

func vnGalleryData() vnGallery {
	g := vnGallery{Themes: []string{"light", "dark"}}
	add := func(groups *[]vnSwatchGroup, tok vnToken) {
		dark := tok.Dark
		if dark == "" {
			dark = tok.Light
		}
		kind := map[string]string{"Type": "text", "Spacing": "space", "Radii": "radius", "Breakpoints": "bp", "Elevation": "shadow"}[tok.Group]
		if strings.HasSuffix(tok.Name, "-lh") {
			kind = "line"
		}
		s := vnSwatch{Name: tok.Name, Light: tok.Light, Dark: dark, Kind: kind, Var: template.CSS("var(" + tok.Name + ")")}
		if n := len(*groups); n > 0 && (*groups)[n-1].Label == tok.Group {
			(*groups)[n-1].Tokens = append((*groups)[n-1].Tokens, s)
			return
		}
		*groups = append(*groups, vnSwatchGroup{Label: tok.Group, Word: vnStateWords[tok.Group], StateStyle: vnStateStyles[tok.Group], Tokens: []vnSwatch{s}})
	}
	for _, tok := range vnTokens {
		switch tok.Group {
		case "ok", "info", "warn", "crit", "idle":
			add(&g.States, tok)
		case "Type", "Spacing", "Radii", "Motion", "Breakpoints":
			add(&g.Scales, tok)
		default:
			add(&g.Colors, tok)
		}
	}
	return g
}

func TestUIGalleryShowsEveryVNextToken(t *testing.T) {
	body := string(galleryHTML(t))
	for _, tok := range vnTokens {
		if !strings.Contains(body, tok.Name) {
			t.Errorf("gallery does not show %s", tok.Name)
		}
	}
	for _, part := range []string{`data-gyst-theme="light"`, `data-gyst-theme="dark"`, "Accent (DD-6)", "never good, warning or bad"} {
		if !strings.Contains(body, part) {
			t.Errorf("gallery token section missing %q", part)
		}
	}
}
